"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface CloudSnowIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface CloudSnowIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const CloudSnowIcon = forwardRef<CloudSnowIconHandle, CloudSnowIconProps>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) {
     controls.start("normal");
    } else {
     onMouseLeave?.(e as any);
    }
   },
   [controls, onMouseLeave],
  );

  const cloudVariants: Variants = {
   normal: { x: 0 },
   animate: {
    x: [0, 1, -1, 0],
    transition: { duration: 1.4 * duration, ease: "easeInOut" },
   },
  };

  const flakeVariants: Variants = {
   normal: { y: 0, opacity: 1 },
   animate: (i: number) => ({
    y: [-3, 0],
    opacity: [0, 1],
    transition: {
     delay: i * 0.09 * duration,
     duration: 0.6 * duration,
     ease: "easeOut",
    },
   }),
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.path
       d="M4 14.899A7 7 0 1 1 15.71 8h1.79a4.5 4.5 0 0 1 2.5 8.242"
       variants={cloudVariants}
      />
      <m.path d="M8 15h.01" custom={0} variants={flakeVariants} />
      <m.path d="M12 17h.01" custom={1} variants={flakeVariants} />
      <m.path d="M16 15h.01" custom={2} variants={flakeVariants} />
      <m.path d="M8 19h.01" custom={3} variants={flakeVariants} />
      <m.path d="M12 21h.01" custom={4} variants={flakeVariants} />
      <m.path d="M16 19h.01" custom={5} variants={flakeVariants} />
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

CloudSnowIcon.displayName = "CloudSnowIcon";
export { CloudSnowIcon };
